// The customer site, Payload and Mailflare share this single tenant Worker.
import { composeTenantWorker, type WorkerHandlerSet } from "./mailflare-runtime"
import { createPayloadOwnerGate } from "./mailflare-owner-gate"
import type { MailflareD1 } from "./mailflare-provisioning"
import { helloAdaSite } from "./src/helloada.config"
// @ts-ignore generated by the OpenNext Cloudflare build
import { default as openNextWorker } from "./.open-next/worker.js"
// @ts-ignore generated by the pinned Mailflare build in the release pipeline
import { default as mailflareWorker } from "./.mailflare/server/index.js"

type RateLimiter = { limit: (input: { key: string }) => Promise<{ success: boolean }> }
type PrivateEmailBucket = {
  get: (key: string) => Promise<{
    arrayBuffer: () => Promise<ArrayBuffer>
    httpMetadata?: { contentType?: string }
    customMetadata?: Record<string, string>
  } | null>
  put: (key: string, value: ArrayBuffer, options: {
    httpMetadata: { contentType: string }
    customMetadata: Record<string, string>
  }) => Promise<unknown>
}
type TenantEnv = {
  HELLOADA_TENANT_ID: string
  D1: MailflareD1
  HELLOADA_TURNSTILE_SECRET_KEY?: string
  HELLOADA_TURNSTILE_SITE_KEY: string
  HELLOADA_MAILFLARE_INBOUND_QUEUE_NAME: string
  HELLOADA_MAILFLARE_OUTBOUND_QUEUE_NAME: string
  HELLOADA_MAILFLARE_AGENT_QUEUE_NAME: string
  EMAIL: unknown
  PRIVATE_EMAIL: PrivateEmailBucket
  RESEND_API_KEY?: string
  MAILFLARE_DB: MailflareD1
  MAILFLARE_ADDRESS: string
  MAILFLARE_ZONE_ID: string
  MAILFLARE_ROUTING_STATUS: string
  MAILFLARE_BUCKET: PrivateEmailBucket
  MAILFLARE_INBOUND_QUEUE: unknown
  MAILFLARE_OUTBOUND_QUEUE: unknown
  MAILFLARE_AGENT_QUEUE: unknown
  MAILFLARE_REALTIME: unknown
  MAILFLARE_AI: unknown
  MAILFLARE_LOGIN_RATE_LIMIT: RateLimiter
  MAILFLARE_AGENT_RATE_LIMIT: RateLimiter
  MAILFLARE_BOOKING_RATE_LIMIT: RateLimiter
}

type MailflareBindings = Record<string, unknown>
type MailflareWorker = WorkerHandlerSet<MailflareBindings>
type WorkerContext = { waitUntil: (promise: Promise<unknown>) => void }

const siteAgentHandlers: WorkerHandlerSet<TenantEnv> = {
  fetch(request, env, context) {
    const handler = openNextWorker as unknown as {
      fetch: (request: Request, env: TenantEnv, context: WorkerContext) => Promise<Response>
    }
    return handler.fetch(request, env, context)
  },
}

const MAILFLARE_BINDING_MAP: Record<string, keyof TenantEnv> = {
  DB: "MAILFLARE_DB",
  BUCKET: "MAILFLARE_BUCKET",
  INBOUND_QUEUE: "MAILFLARE_INBOUND_QUEUE",
  EMAIL: "EMAIL",
  OUTBOUND_QUEUE: "MAILFLARE_OUTBOUND_QUEUE",
  AGENT_QUEUE: "MAILFLARE_AGENT_QUEUE",
  REALTIME: "MAILFLARE_REALTIME",
  AI: "MAILFLARE_AI",
  LOGIN_RATE_LIMIT: "MAILFLARE_LOGIN_RATE_LIMIT",
  AGENT_RATE_LIMIT: "MAILFLARE_AGENT_RATE_LIMIT",
  BOOKING_RATE_LIMIT: "MAILFLARE_BOOKING_RATE_LIMIT",
  TURNSTILE_SECRET_KEY: "HELLOADA_TURNSTILE_SECRET_KEY",
  TURNSTILE_SITE_KEY: "HELLOADA_TURNSTILE_SITE_KEY",
  RESEND_API_KEY: "RESEND_API_KEY",
}

const asMailflareEnv = (env: TenantEnv) => new Proxy(env as unknown as Record<string, unknown>, {
  get(target, property, receiver) {
    const mapped = typeof property === "string" ? MAILFLARE_BINDING_MAP[property] : undefined
    return Reflect.get(target, mapped ?? property, receiver)
  },
}) as MailflareBindings

const mailflare = mailflareWorker as unknown as MailflareWorker

const mailflareOwnerGate = createPayloadOwnerGate<TenantEnv, WorkerContext>({
  basePath: "/mail",
  defaultLocale: helloAdaSite.defaultLocale,
  resolveIdentity: async (request, env, context) => {
    const cookie = request.headers.get("cookie")
    if (!cookie) return null
    const identityRequest = new Request("https://helloada-internal.invalid/api/helloada/mailflare-identity", {
      headers: { accept: "application/json", cookie },
    })
    const response = await (openNextWorker as unknown as {
      fetch: (request: Request, env: TenantEnv, context: WorkerContext) => Promise<Response>
    }).fetch(identityRequest, env, context)
    if (response.status === 401) return null
    if (!response.ok) throw new Error("Payload could not confirm the authenticated owner identity")
    const identity = await response.json() as { subject?: unknown }
    if (typeof identity.subject !== "string" || !identity.subject.trim()) {
      throw new Error("Payload owner identity did not contain a stable subject")
    }
    return { subject: identity.subject.trim() }
  },
  logout: async (request, env, context) => {
    const cookie = request.headers.get("cookie")
    if (!cookie) return new Response(null, { status: 204 })
    const payloadLogout = new Request("https://helloada-internal.invalid/api/users/logout", {
      method: "POST",
      headers: { accept: "application/json", cookie },
    })
    return (openNextWorker as unknown as {
      fetch: (request: Request, env: TenantEnv, context: WorkerContext) => Promise<Response>
    }).fetch(payloadLogout, env, context)
  },
})

export default composeTenantWorker({
  site: siteAgentHandlers,
  mailflare,
  mailflareEnv: asMailflareEnv,
  mailflareRequest: mailflareOwnerGate,
  mailflareQueueNames: (env: TenantEnv) => [
    env.HELLOADA_MAILFLARE_INBOUND_QUEUE_NAME,
    env.HELLOADA_MAILFLARE_OUTBOUND_QUEUE_NAME,
    env.HELLOADA_MAILFLARE_AGENT_QUEUE_NAME,
  ],
  basePath: "/mail",
})

